#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

struct Node* insertAtStart(struct Node* head, int value);
struct Node* insertAtEnd(struct Node* head, int value);
struct Node* deleteAtStart(struct Node* head);
struct Node* deleteAtEnd(struct Node* head);
int search(struct Node* head, int key);
void printList(struct Node* head);
void sortList(struct Node* head);

int main() {
    struct Node* head = NULL;
    int choice, value;

    while (1) {
        printf("\nMenu:\n");
        printf("1. Insert at Start\n2. Insert at End\n3. Delete at Start\n4. Delete at End\n5. Search\n6. Print\n7. Sort\n8. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter value: ");
                scanf("%d", &value);
                head = insertAtStart(head, value);
                break;
            case 2:
                printf("Enter value: ");
                scanf("%d", &value);
                head = insertAtEnd(head, value);
                break;
            case 3:
                head = deleteAtStart(head);
                break;
            case 4:
                head = deleteAtEnd(head);
                break;
            case 5:
                printf("Enter value: ");
                scanf("%d", &value);
                if (search(head, value))
                    printf("Found!\n");
                else
                    printf("Not Found!\n");
                break;
            case 6:
                printList(head);
                break;
            case 7:
                sortList(head);
                break;
            case 8:
                exit(0);
        }
    }
}
```

---

## 🔹 6. Exam/Interview Tricks

1. **Draw Diagrams**: Always show before/after insertion/deletion → instant marks.  
2. **Always check empty list** → safe code.  
3. **Head changes? Return it** (Insert/Delete at start).  
4. **Practice dry runs**: Use 3 nodes always.  
5. For interviews: Be ready to talk about **time complexity**.  

