# 🔹 Delete in CLL

### Delete at Start
```c
struct Node* deleteAtStart(struct Node* head) {
    if (head == NULL) return NULL;

    if (head->next == head) { // only one node
        free(head);
        return NULL;
    }

    struct Node* temp = head;
    while (temp->next != head) { // reach last node
        temp = temp->next;
    }

    struct Node* toDelete = head;
    head = head->next;
    temp->next = head;
    free(toDelete);

    return head;
}
```

---

### Delete at End
```c
struct Node* deleteAtEnd(struct Node* head) {
    if (head == NULL) return NULL;

    if (head->next == head) { // only one node
        free(head);
        return NULL;
    }

    struct Node* temp = head;
    while (temp->next->next != head) { // reach second-last
        temp = temp->next;
    }

    struct Node* toDelete = temp->next; // last node
    temp->next = head;
    free(toDelete);

    return head;
}
```

